insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'journey', 'first-week', 'en', 1, 'active', p.id, null, null, null, 'Your first week', 'A recommended action plan — not a promise of results.', '{"disclaimer":"A recommended plan to build a routine. Results depend on your work, your market and your prospects; nothing here is a promise of sales or income.","days":[{"day":1,"title":"Understand Studio ATS","body":"Read Product knowledge and one playbook.","tasks":["Read what Studio ATS is and what’s included","Open the playbook for your target"]},{"day":2,"title":"Choose 20 prospects","body":"Pick one target and list 20 real businesses near you.","tasks":["Choose your target","Add 20 prospects to your CRM"]},{"day":3,"title":"Contact your first prospects","body":"Send your first personalised messages.","tasks":["Send 5 first-contact messages","Create your sales page for the target"]},{"day":4,"title":"Follow up","body":"Follow up with those who haven’t answered — once, briefly.","tasks":["Send follow-ups","Move replies to “Replied”"]},{"day":5,"title":"Run calls","body":"Use the call script with those who replied.","tasks":["Run at least one discovery call","Log the next step for each call"]},{"day":6,"title":"Send relevant sales pages","body":"Send your page to qualified prospects.","tasks":["Send your sales page after each call","Check that the page looks right on mobile"]},{"day":7,"title":"Review","body":"Look at what worked: which message, which target, which channel.","tasks":["Review your page and link performance","Plan next week"]}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'journey', 'first-week', 'fr', 1, 'active', p.id, null, null, null, 'Votre première semaine', 'Un plan d’action recommandé — pas une promesse de résultats.', '{"disclaimer":"Un plan recommandé pour prendre un rythme. Les résultats dépendent de votre travail, de votre marché et de vos prospects ; rien ici n’est une promesse de ventes ou de revenus.","days":[{"day":1,"title":"Comprendre Studio ATS","body":"Lisez la fiche produit et un playbook.","tasks":["Lire ce qu’est Studio ATS et ce qui est inclus","Ouvrir le playbook de votre cible"]},{"day":2,"title":"Choisir 20 prospects","body":"Choisissez une cible et listez 20 vraies entreprises près de chez vous.","tasks":["Choisir votre cible","Ajouter 20 prospects au CRM"]},{"day":3,"title":"Contacter vos premiers prospects","body":"Envoyez vos premiers messages personnalisés.","tasks":["Envoyer 5 messages de premier contact","Créer votre page commerciale pour la cible"]},{"day":4,"title":"Relancer","body":"Relancez ceux qui n’ont pas répondu — une fois, brièvement.","tasks":["Envoyer les relances","Passer les réponses en « A répondu »"]},{"day":5,"title":"Faire des appels","body":"Utilisez le script d’appel avec ceux qui ont répondu.","tasks":["Mener au moins un appel découverte","Noter la prochaine étape de chaque appel"]},{"day":6,"title":"Envoyer les pages commerciales","body":"Envoyez votre page aux prospects qualifiés.","tasks":["Envoyer votre page après chaque appel","Vérifier l’affichage de la page sur mobile"]},{"day":7,"title":"Faire le point","body":"Regardez ce qui a marché : quel message, quelle cible, quel canal.","tasks":["Consulter les performances de votre page et de vos liens","Planifier la semaine suivante"]}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'pitch', 'studio', 'en', 1, 'active', p.id, null, null, null, 'Studio in 15 seconds', 'What Studio is, for whom, and what the client really buys.', '{"oneLiner":"Studio becomes your digital team and infrastructure.","short":"Studio becomes the digital team of your business: we build your online presence, connect your tools, and run it for you — so you focus on your clients.","medium":"Most businesses juggle a website, social media, a booking tool, emails, spreadsheets — and nobody really owns it. Studio takes that over: we build your digital infrastructure, connect your tools so requests, clients and follow-ups live in one place, and we keep it running all year. You don’t buy a website, you get a team.","long":"Studio is a team that builds and runs the digital side of a business.\n\n1. We start from how you work today: how clients find you, contact you, buy, and how you follow them.\n2. We build what is missing — presentation, request forms, booking, shop, client space — and connect the tools you already use.\n3. We run it: hosting, security, backups, updates and changes, without you touching anything technical.\n\nThree levels depending on how much you want us to handle: Studio One (a ready-to-use presence you own), Studio Pro (a complete site maintained all year), Studio Premium (your whole commercial ecosystem — CRM, payments, automations — operated by Studio).","problem":"Small businesses pile up tools nobody maintains: a dated website, social accounts, a booking app, emails and spreadsheets. Requests get lost, follow-ups are forgotten, and every change depends on someone who isn’t there.","forWhom":"Independents, small businesses and growing companies that sell a service or a product and don’t have — or don’t want — an internal digital team.","whatTheyBuy":["A team that builds and runs their digital side","Their tools connected: requests, clients and follow-ups in one place","Peace of mind: hosting, security, backups and updates handled","Code and data they own"],"notThis":["Not “just a website”","Not “just a CRM”","Not a pile of software subscriptions","Not a promise of revenue — a team and an infrastructure"]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'pitch', 'studio', 'fr', 1, 'active', p.id, null, null, null, 'Studio en 15 secondes', 'Ce qu’est Studio, pour qui, et ce que le client achète vraiment.', '{"oneLiner":"Studio devient votre équipe et votre infrastructure numérique.","short":"Studio devient l’équipe numérique de votre entreprise : on construit votre présence en ligne, on connecte vos outils et on fait tout fonctionner pour vous — vous, vous vous occupez de vos clients.","medium":"La plupart des entreprises jonglent entre un site, des réseaux sociaux, un outil de réservation, des emails, des tableurs — et personne ne s’en occupe vraiment. Studio prend le relais : on construit votre infrastructure numérique, on connecte vos outils pour que demandes, clients et relances soient au même endroit, et on la fait fonctionner toute l’année. Vous n’achetez pas un site, vous gagnez une équipe.","long":"Studio est une équipe qui construit et fait fonctionner le numérique d’une entreprise.\n\n1. On part de votre fonctionnement actuel : comment les clients vous trouvent, vous contactent, achètent, et comment vous les suivez.\n2. On construit ce qui manque — présentation, formulaires de demande, réservation, boutique, espace client — et on connecte les outils que vous utilisez déjà.\n3. On fait tourner le tout : hébergement, sécurité, sauvegardes, mises à jour et modifications, sans que vous touchiez à la technique.\n\nTrois niveaux selon ce que vous voulez nous confier : Studio One (une présence prête à l’emploi qui vous appartient), Studio Pro (un site complet maintenu toute l’année), Studio Premium (tout votre écosystème commercial — CRM, paiements, automatisations — opéré par Studio).","problem":"Les petites entreprises empilent des outils que personne ne maintient : un site daté, des comptes sociaux, une appli de réservation, des emails et des tableurs. Des demandes se perdent, les relances sont oubliées, et chaque changement dépend de quelqu’un qui n’est pas là.","forWhom":"Indépendants, petites entreprises et sociétés en croissance qui vendent un service ou un produit et qui n’ont pas — ou ne veulent pas — d’équipe numérique interne.","whatTheyBuy":["Une équipe qui construit et fait fonctionner leur numérique","Leurs outils connectés : demandes, clients et relances au même endroit","La tranquillité : hébergement, sécurité, sauvegardes et mises à jour gérés","Un code et des données qui leur appartiennent"],"notThis":["Pas « juste un site »","Pas « juste un CRM »","Pas une pile d’abonnements logiciels","Pas une promesse de chiffre d’affaires — une équipe et une infrastructure"]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'diagnostic', 'core', 'en', 1, 'active', p.id, null, null, null, '7 questions to guide the conversation', 'Ask, listen, and note the answers in the prospect’s card.', '{"intro":"You don’t need to know the technique. Ask one question at a time and let them talk: every answer tells you what Studio can take off their hands.","questions":[{"question":"How do you manage your prospects today?","listenFor":"Memory, notebook, phone contacts, scattered emails.","studio":"Every request and contact in one place, with history."},{"question":"How do you follow up with people who haven’t answered?","listenFor":"“I don’t”, “when I have time”, “I forget”.","studio":"Follow-ups planned and prepared, so none is forgotten."},{"question":"Who manages your website and digital tools?","listenFor":"A nephew, a freelancer who left, “nobody”, “me, at night”.","studio":"A team that builds, hosts, secures and updates everything."},{"question":"How many different tools do you use for your clients?","listenFor":"Several apps, subscriptions, spreadsheets that don’t talk to each other.","studio":"Tools connected — or replaced — in one infrastructure."},{"question":"What happens when a prospect contacts you?","listenFor":"Missed calls, DMs answered days later, requests without details.","studio":"Requests that arrive complete, and an answer path that works even when they’re busy."},{"question":"How do you keep track of your clients after a sale?","listenFor":"No follow-up, no news, no second sale.","studio":"Client history and follow-ups that bring them back."},{"question":"What makes you lose the most time today?","listenFor":"Admin, repetitive questions, re-typing, chasing information.","studio":"Automate the repetitive part — they keep the human part."},{"question":"Where can a new enquiry arrive today?","listenFor":"Phone, email, DMs and forms monitored by different people.","studio":"Bring requests into one visible flow."},{"question":"Who owns the next action after an enquiry?","listenFor":"No named owner, shared inbox, or the founder does everything.","studio":"Give each opportunity an owner, stage and next action."},{"question":"What information is usually missing before the first call?","listenFor":"Budget, timing, service, location or decision-maker.","studio":"Collect useful context before the conversation."},{"question":"What happens when you are unavailable for a day?","listenFor":"Requests wait, appointments stop, nobody has access.","studio":"Keep safe next steps working without the owner."},{"question":"Which customer question do you answer every week?","listenFor":"Prices, availability, process, documents or opening hours.","studio":"Put reliable answers at the right point in the journey."},{"question":"How are appointments arranged and confirmed?","listenFor":"Back-and-forth messages, double booking, forgotten reminders.","studio":"Connect booking, confirmations and reminders when relevant."},{"question":"How do you know which channel brought a customer?","listenFor":"Guesswork, no source field, inconsistent tracking.","studio":"Track useful sources and campaigns."},{"question":"What do you copy from one tool into another?","listenFor":"Repeated entry between forms, email, spreadsheets, CRM and invoices.","studio":"Connect the flow and remove avoidable re-entry."},{"question":"Who updates your online information when something changes?","listenFor":"Nobody, an unavailable freelancer, several inconsistent places.","studio":"Create a maintainable source with an operating owner."},{"question":"How do you know a prospect has gone cold?","listenFor":"Memory, inbox searching, no agreed follow-up cadence.","studio":"Make inactivity and the next follow-up visible."},{"question":"Which part of the customer journey causes the most errors?","listenFor":"Handoffs, missing information, manual confirmation or payment status.","studio":"Redesign the weak handoff before adding technology."},{"question":"What have you already tried to fix this?","listenFor":"Unused tools, partial setup, abandoned project, training without ownership.","studio":"Preserve what works and take responsibility for the missing system."},{"question":"What would a good result look like in daily work?","listenFor":"Less repetition, clearer status, faster response, fewer lost requests.","studio":"Define an operational outcome without promising revenue."}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'diagnostic', 'core', 'fr', 1, 'active', p.id, null, null, null, '7 questions pour guider la conversation', 'Posez, écoutez, et notez les réponses dans la fiche du prospect.', '{"intro":"Pas besoin de connaître la technique. Posez une question à la fois et laissez parler : chaque réponse vous dit ce que Studio peut leur enlever.","questions":[{"question":"Comment gérez-vous actuellement vos prospects ?","listenFor":"De tête, un carnet, les contacts du téléphone, des emails éparpillés.","studio":"Toutes les demandes et contacts au même endroit, avec l’historique."},{"question":"Comment effectuez-vous vos relances ?","listenFor":"« Je n’en fais pas », « quand j’ai le temps », « j’oublie ».","studio":"Des relances planifiées et préparées, aucune n’est oubliée."},{"question":"Qui gère votre infrastructure numérique ?","listenFor":"Un neveu, un freelance parti, « personne », « moi, le soir ».","studio":"Une équipe qui construit, héberge, sécurise et met tout à jour."},{"question":"Combien d’outils différents utilisez-vous ?","listenFor":"Plusieurs applis, abonnements et tableurs qui ne se parlent pas.","studio":"Des outils connectés — ou remplacés — dans une seule infrastructure."},{"question":"Que se passe-t-il lorsqu’un prospect vous contacte ?","listenFor":"Appels manqués, DM répondus des jours plus tard, demandes sans détails.","studio":"Des demandes complètes et un parcours de réponse qui fonctionne même quand ils sont occupés."},{"question":"Comment suivez-vous vos clients ?","listenFor":"Aucun suivi, pas de nouvelles, pas de deuxième vente.","studio":"Un historique client et des relances qui les font revenir."},{"question":"Qu’est-ce qui vous fait perdre du temps actuellement ?","listenFor":"Administratif, questions répétitives, ressaisies, informations à aller chercher.","studio":"Automatiser le répétitif — ils gardent la partie humaine."},{"question":"Où une nouvelle demande peut-elle arriver aujourd’hui ?","listenFor":"Téléphone, email, DM et formulaires surveillés par des personnes différentes.","studio":"Réunir les demandes dans un parcours visible."},{"question":"Qui porte la prochaine action après une demande ?","listenFor":"Aucun responsable nommé, boîte partagée, ou le dirigeant fait tout.","studio":"Donner à chaque opportunité un responsable, une étape et une prochaine action."},{"question":"Quelle information manque le plus souvent avant le premier appel ?","listenFor":"Budget, délai, service, localisation ou décideur.","studio":"Recueillir le contexte utile avant la conversation."},{"question":"Que se passe-t-il si vous êtes indisponible une journée ?","listenFor":"Les demandes attendent, les rendez-vous s’arrêtent, personne n’a accès.","studio":"Maintenir les prochaines étapes sûres sans dépendre du dirigeant."},{"question":"À quelle question client répondez-vous chaque semaine ?","listenFor":"Prix, disponibilité, processus, documents ou horaires.","studio":"Placer les réponses fiables au bon endroit dans le parcours."},{"question":"Comment les rendez-vous sont-ils organisés et confirmés ?","listenFor":"Allers-retours de messages, doublons, rappels oubliés.","studio":"Relier réservation, confirmations et rappels lorsque c’est pertinent."},{"question":"Comment savez-vous quel canal a apporté un client ?","listenFor":"Intuition, aucune source enregistrée, suivi incohérent.","studio":"Suivre les sources et campagnes utiles."},{"question":"Que recopiez-vous d’un outil dans un autre ?","listenFor":"Saisies répétées entre formulaires, email, tableurs, CRM et factures.","studio":"Connecter le parcours et supprimer les ressaisies évitables."},{"question":"Qui met à jour vos informations en ligne lorsqu’elles changent ?","listenFor":"Personne, un prestataire indisponible, plusieurs endroits incohérents.","studio":"Créer une source maintenable avec un responsable opérationnel."},{"question":"Comment savez-vous qu’un prospect s’est refroidi ?","listenFor":"Mémoire, recherche dans la boîte mail, aucune cadence de relance convenue.","studio":"Rendre visibles l’inactivité et la prochaine relance."},{"question":"Quelle étape du parcours client provoque le plus d’erreurs ?","listenFor":"Passage de relais, information manquante, confirmation manuelle ou statut de paiement.","studio":"Repenser le passage fragile avant d’ajouter de la technologie."},{"question":"Qu’avez-vous déjà essayé pour résoudre ce problème ?","listenFor":"Outils inutilisés, configuration partielle, projet abandonné, formation sans responsable.","studio":"Conserver ce qui fonctionne et prendre en charge le système manquant."},{"question":"À quoi ressemblerait un bon résultat dans votre quotidien ?","listenFor":"Moins de répétition, statut plus clair, réponse plus rapide, moins de demandes perdues.","studio":"Définir un résultat opérationnel sans promettre de chiffre d’affaires."}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sequence', 'no-reply', 'en', 1, 'active', p.id, null, null, 'follow_up', 'No reply after the first message', 'Five touches over a month, then stop.', '{"intro":"Applies to prospects in “Contacted”. One short touch at a time — never insist after J+30.","steps":[{"day":1,"channel":"linkedin","goal":"Soft touch","text":"Hello {{firstName}}, I sent you a short message yesterday about {{company}} — no rush, I’m around if the question speaks to you."},{"day":3,"channel":"whatsapp","goal":"Short reminder","text":"Hello {{firstName}}, I’m bringing my message back up: how do new clients reach {{company}} today? If it’s not a topic for you, just tell me."},{"day":7,"channel":"email","goal":"Bring value: show a similar project","text":"Hello {{firstName}}, here is an example of what Studio built for a business close to yours — it shows in one minute what I meant: {{affiliateUrl}}"},{"day":14,"channel":"other","goal":"One direct question","text":"Hello {{firstName}}, one simple question and I’ll stop there: is organising your requests and follow-ups a topic for you this year, yes or no?"},{"day":30,"channel":"email","goal":"Close the loop","text":"Hello {{firstName}}, I won’t follow up again — I don’t want to clutter your inbox. If one day you want a team to handle the digital side of {{company}}, everything is here: {{affiliateUrl}}"}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sequence', 'no-reply', 'fr', 1, 'active', p.id, null, null, 'follow_up', 'Pas de réponse après le premier message', 'Cinq relances sur un mois, puis on s’arrête.', '{"intro":"S’applique aux prospects « Contactés ». Une relance courte à la fois — on n’insiste jamais après J+30.","steps":[{"day":1,"channel":"linkedin","goal":"Contact léger","text":"Bonjour {{firstName}}, je vous ai envoyé un petit message hier au sujet de {{company}} — rien d’urgent, je reste disponible si la question vous parle."},{"day":3,"channel":"whatsapp","goal":"Relance courte","text":"Bonjour {{firstName}}, je remonte mon message : comment les nouveaux clients contactent-ils {{company}} aujourd’hui ? Si ce n’est pas un sujet pour vous, dites-le-moi simplement."},{"day":7,"channel":"email","goal":"Apporter de la valeur : montrer un projet proche","text":"Bonjour {{firstName}}, voici un exemple de ce que Studio a réalisé pour une activité proche de la vôtre — ça montre en une minute ce que je voulais dire : {{affiliateUrl}}"},{"day":14,"channel":"other","goal":"Une question directe","text":"Bonjour {{firstName}}, une question simple et je m’arrête là : organiser vos demandes et vos relances, c’est un sujet pour vous cette année, oui ou non ?"},{"day":30,"channel":"email","goal":"Clore proprement","text":"Bonjour {{firstName}}, je ne vous relancerai plus — je ne veux pas encombrer votre boîte. Si un jour vous voulez une équipe pour gérer le numérique de {{company}}, tout est ici : {{affiliateUrl}}"}]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sequence', 'after-proposal', 'en', 1, 'active', p.id, null, null, 'proposal', 'After sending the offer', 'Help them decide without pressure.', '{"intro":"Applies to prospects in “Proposal” or “Checkout”. You answer questions; you never negotiate the price.","steps":[{"day":1,"channel":"whatsapp","goal":"Check it arrived","text":"Hello {{firstName}}, did you get the Studio offer? Any first question, even a small one?"},{"day":3,"channel":"phone","goal":"Offer a 10-minute call","text":"Hello {{firstName}}, would 10 minutes this week help to go over the offer together? I can answer what’s still unclear."},{"day":7,"channel":"email","goal":"Answer the usual doubt","text":"Hello {{firstName}}, people often ask me the same question at this stage: what exactly Studio handles after the launch. Short answer: hosting, security, backups and changes — you don’t touch anything technical. Shall we talk about it?"},{"day":14,"channel":"other","goal":"Ask for a decision","text":"Hello {{firstName}}, where are you on Studio for {{company}}? A “not now” is a perfectly fine answer — it helps me know when to come back."}]}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'sequence', 'after-proposal', 'fr', 1, 'active', p.id, null, null, 'proposal', 'Après l’envoi de l’offre', 'Aider à décider, sans pression.', '{"intro":"S’applique aux prospects en « Proposition » ou « Paiement ». Vous répondez aux questions ; vous ne négociez jamais le prix.","steps":[{"day":1,"channel":"whatsapp","goal":"Vérifier la réception","text":"Bonjour {{firstName}}, vous avez bien reçu l’offre Studio ? Une première question, même petite ?"},{"day":3,"channel":"phone","goal":"Proposer 10 minutes d’appel","text":"Bonjour {{firstName}}, 10 minutes cette semaine pour parcourir l’offre ensemble, ça vous aiderait ? Je peux répondre à ce qui reste flou."},{"day":7,"channel":"email","goal":"Lever le doute habituel","text":"Bonjour {{firstName}}, on me pose souvent la même question à ce stade : ce que Studio gère exactement après la mise en ligne. Réponse courte : hébergement, sécurité, sauvegardes et modifications — vous ne touchez à rien de technique. On en parle ?"},{"day":14,"channel":"other","goal":"Demander une décision","text":"Bonjour {{firstName}}, où en êtes-vous pour Studio chez {{company}} ? Un « pas maintenant » est une très bonne réponse — ça m’aide à savoir quand revenir vers vous."}]}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-instagram', 'en', 1, 'active', p.id, null, 'instagram', 'first_contact', 'First contact — Instagram DM', null, '{"text":"Hello {{firstName}}! I really like what you post for {{company}} 👏 Quick question: when someone wants to work with you after seeing a post, how do they contact you? I work with Studio, a team that builds and runs the digital side of businesses like yours. Happy to show you an example if you’re curious."}'::jsonb, array['instagram', 'dm', 'ton:chaleureux']::text[], 60, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-instagram', 'fr', 1, 'active', p.id, null, 'instagram', 'first_contact', 'Premier contact — DM Instagram', null, '{"text":"Bonjour {{firstName}} ! J’aime beaucoup ce que vous publiez pour {{company}} 👏 Petite question : quand quelqu’un veut travailler avec vous après avoir vu un post, comment vous contacte-t-il ? Je travaille avec Studio, une équipe qui construit et fait fonctionner le numérique d’entreprises comme la vôtre. Je peux vous montrer un exemple si ça vous intrigue."}'::jsonb, array['instagram', 'dm', 'ton:chaleureux']::text[], 60, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-direct', 'en', 1, 'active', p.id, null, 'other', 'first_contact', 'First contact — direct tone', null, '{"text":"Hello {{firstName}}, I’m {{advisorName}}. I work with Studio, which becomes the digital team of businesses: website, tools, requests and follow-ups built and run for them. For {{company}}, I think there’s a quick win. 10 minutes this week?"}'::jsonb, array['ton:direct', 'premier contact']::text[], 61, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-direct', 'fr', 1, 'active', p.id, null, 'other', 'first_contact', 'Premier contact — ton direct', null, '{"text":"Bonjour {{firstName}}, je suis {{advisorName}}. Je travaille avec Studio, qui devient l’équipe numérique des entreprises : site, outils, demandes et relances construits et gérés pour elles. Pour {{company}}, je pense qu’il y a quelque chose de simple à gagner. 10 minutes cette semaine ?"}'::jsonb, array['ton:direct', 'premier contact']::text[], 61, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-warm', 'en', 1, 'active', p.id, null, 'other', 'first_contact', 'First contact — warm tone (someone you know)', null, '{"text":"Hi {{firstName}}, how are you? I’ve started working with Studio, a team that handles the whole digital side of businesses — site, tools, requests, follow-ups. I immediately thought of {{company}}. Can I tell you about it over a coffee or a quick call?"}'::jsonb, array['ton:chaleureux', 'premier contact', 'réseau']::text[], 62, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'first-contact-warm', 'fr', 1, 'active', p.id, null, 'other', 'first_contact', 'Premier contact — ton chaleureux (quelqu’un que vous connaissez)', null, '{"text":"Salut {{firstName}}, comment vas-tu ? J’ai commencé à travailler avec Studio, une équipe qui prend en charge tout le numérique des entreprises — site, outils, demandes, relances. J’ai tout de suite pensé à {{company}}. Je t’en parle autour d’un café ou d’un appel rapide ?"}'::jsonb, array['ton:chaleureux', 'premier contact', 'réseau']::text[], 62, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'interested-reply', 'en', 1, 'active', p.id, null, 'other', 'interested', 'Reply after interest', null, '{"text":"Great, thank you {{firstName}}! To show you something relevant rather than a generic presentation, I have two questions: how do new clients contact you today, and who manages your tools? Then I’ll send you a concrete example close to {{company}}."}'::jsonb, array['intérêt', 'interested']::text[], 63, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'interested-reply', 'fr', 1, 'active', p.id, null, 'other', 'interested', 'Réponse après un intérêt', null, '{"text":"Super, merci {{firstName}} ! Pour vous montrer quelque chose de pertinent plutôt qu’une présentation générique, j’ai deux questions : comment les nouveaux clients vous contactent-ils aujourd’hui, et qui gère vos outils ? Ensuite je vous envoie un exemple concret proche de {{company}}."}'::jsonb, array['intérêt', 'interested']::text[], 63, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'meeting-proposal', 'en', 1, 'active', p.id, null, 'other', 'interested', 'Propose a meeting', null, '{"text":"{{firstName}}, the simplest is to look at it together: 20 minutes, I show you a project close to {{company}} and we see what Studio could take off your hands. Would Tuesday or Thursday suit you, morning or afternoon?"}'::jsonb, array['rendez-vous', 'meeting', 'appel']::text[], 64, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'meeting-proposal', 'fr', 1, 'active', p.id, null, 'other', 'interested', 'Proposition de rendez-vous', null, '{"text":"{{firstName}}, le plus simple est de regarder ensemble : 20 minutes, je vous montre un projet proche de {{company}} et on voit ce que Studio pourrait vous enlever. Mardi ou jeudi, plutôt matin ou après-midi ?"}'::jsonb, array['rendez-vous', 'meeting', 'appel']::text[], 64, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'share-reference', 'en', 1, 'active', p.id, null, 'other', 'follow_up', 'Share a similar project', null, '{"text":"Hello {{firstName}}, here is a project Studio built for a business close to yours — take a look on your phone, it speaks for itself. I can explain how the same thing would work for {{company}}: {{affiliateUrl}}"}'::jsonb, array['référence', 'projet', 'exemple']::text[], 65, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'share-reference', 'fr', 1, 'active', p.id, null, 'other', 'follow_up', 'Partager un projet proche', null, '{"text":"Bonjour {{firstName}}, voici un projet réalisé par Studio pour une activité proche de la vôtre — regardez-le sur votre téléphone, il parle de lui-même. Je peux vous expliquer comment la même chose fonctionnerait pour {{company}} : {{affiliateUrl}}"}'::jsonb, array['référence', 'projet', 'exemple']::text[], 65, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'silence-revive', 'en', 1, 'active', p.id, null, 'email', 'no_response', 'Revive after a long silence', null, '{"text":"Hello {{firstName}}, we talked a while ago about the digital side of {{company}}. A lot of businesses come back to the topic before a busy season — is it a better time now? If not, no problem at all."}'::jsonb, array['silence', 'relance', 'réactiver']::text[], 66, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'message', 'silence-revive', 'fr', 1, 'active', p.id, null, 'email', 'no_response', 'Relance après un long silence', null, '{"text":"Bonjour {{firstName}}, nous avions échangé il y a quelque temps sur le numérique de {{company}}. Beaucoup d’entreprises reviennent sur le sujet avant une période chargée — est-ce un meilleur moment maintenant ? Sinon, aucun souci."}'::jsonb, array['silence', 'relance', 'réactiver']::text[], 66, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-crm', 'en', 1, 'active', p.id, null, null, 'objection', '“I already have a CRM.”', null, '{"objection":"“I already have a CRM.”","meaning":"They think Studio is one more piece of software.","questions":["Who set it up, and who keeps it up to date?","Is it connected to your website and your requests?"],"short":"Great — Studio isn’t one more tool: it’s the team that connects your tools and keeps them working together.","long":"A CRM is only as good as what feeds it. Often, requests from the website, social media and phone never reach it, and nobody has time to maintain it. Studio starts from what you already use: we connect it, fill the gaps around it and run the whole thing. If your CRM is right for you, we keep it.","nextStep":"Ask which tools they use, and note them in the prospect card for the Studio team.","proof":"Show a project where requests and follow-ups are centralised."}'::jsonb, array['crm', 'hubspot', 'salesforce', 'pipedrive', 'outil', 'logiciel', 'software']::text[], 80, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'already-crm', 'fr', 1, 'active', p.id, null, null, 'objection', '« J’ai déjà un CRM. »', null, '{"objection":"« J’ai déjà un CRM. »","meaning":"Ils pensent que Studio est un logiciel de plus.","questions":["Qui l’a mis en place, et qui le tient à jour ?","Est-il relié à votre site et à vos demandes ?"],"short":"Très bien — Studio n’est pas un outil de plus : c’est l’équipe qui connecte vos outils et les fait fonctionner ensemble.","long":"Un CRM ne vaut que par ce qui l’alimente. Souvent, les demandes du site, des réseaux et du téléphone n’y arrivent jamais, et personne n’a le temps de le maintenir. Studio part de ce que vous utilisez déjà : on le connecte, on complète ce qui manque autour et on fait tourner l’ensemble. Si votre CRM vous convient, on le garde.","nextStep":"Demandez quels outils ils utilisent et notez-les dans la fiche prospect pour l’équipe Studio.","proof":"Montrez un projet où demandes et relances sont centralisées."}'::jsonb, array['crm', 'hubspot', 'salesforce', 'pipedrive', 'outil', 'logiciel', 'software']::text[], 80, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'do-it-myself', 'en', 1, 'active', p.id, null, null, 'objection', '“I can do it myself.”', null, '{"objection":"“I can do it myself.”","meaning":"They can build pages — and underestimate what comes after.","questions":["How much time would you spend on it each month?","Who handles it when something breaks or needs changing?"],"short":"You could build a site, yes. Studio is about everything after: running it, connecting it, securing it — while you work on your business.","long":"Building a page is the easy part. What takes time is everything around it: connecting the tools, keeping it secure, backups, updates, changes, follow-ups that go out on time. Studio is a team that handles that all year. The real question is: is it the best use of your time?","nextStep":"Ask what their hour is worth to them, and compare with the offer — never negotiate the price."}'::jsonb, array['moi-même', 'myself', 'wix', 'wordpress', 'squarespace', 'diy', 'neveu']::text[], 81, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'do-it-myself', 'fr', 1, 'active', p.id, null, null, 'objection', '« Je peux le faire moi-même. »', null, '{"objection":"« Je peux le faire moi-même. »","meaning":"Ils savent faire des pages — et sous-estiment ce qui vient après.","questions":["Combien de temps y passeriez-vous chaque mois ?","Qui s’en occupe quand quelque chose casse ou doit changer ?"],"short":"Vous pourriez faire un site, oui. Studio, c’est tout ce qui vient après : le faire fonctionner, le connecter, le sécuriser — pendant que vous travaillez sur votre activité.","long":"Faire une page, c’est la partie facile. Ce qui prend du temps, c’est tout le reste : connecter les outils, sécuriser, sauvegarder, mettre à jour, modifier, envoyer les relances à temps. Studio est une équipe qui gère cela toute l’année. La vraie question : est-ce le meilleur usage de votre temps ?","nextStep":"Demandez ce que vaut une heure de leur temps et comparez avec l’offre — sans jamais négocier le prix."}'::jsonb, array['moi-même', 'myself', 'wix', 'wordpress', 'squarespace', 'diy', 'neveu']::text[], 81, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'dont-understand', 'en', 1, 'active', p.id, null, null, 'objection', '“I don’t understand exactly what you do.”', null, '{"objection":"“I don’t understand exactly what you do.”","meaning":"The pitch was too abstract — bring it back to their day.","questions":["Can I ask how a new client reaches you today?","Which part of your digital side annoys you the most?"],"short":"Simply: we become your digital team. We build your online presence, connect your tools and run everything for you.","long":"Forget the technical words. Think of an employee in charge of everything digital: the site, requests, follow-ups, tools, security. Studio is that team, for a fixed price, without hiring. Then show one concrete project close to their business — it’s always clearer than an explanation.","nextStep":"Send one similar project from the copilot, then propose 20 minutes.","proof":"Show the closest project from the copilot."}'::jsonb, array['comprends pas', 'understand', 'c’est quoi', 'what is', 'flou', 'unclear']::text[], 82, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'dont-understand', 'fr', 1, 'active', p.id, null, null, 'objection', '« Je ne comprends pas exactement ce que vous faites. »', null, '{"objection":"« Je ne comprends pas exactement ce que vous faites. »","meaning":"Le pitch était trop abstrait — ramenez-le à leur quotidien.","questions":["Je peux vous demander comment un nouveau client vous contacte aujourd’hui ?","Quelle partie de votre numérique vous agace le plus ?"],"short":"Simplement : on devient votre équipe numérique. On construit votre présence en ligne, on connecte vos outils et on fait tout fonctionner pour vous.","long":"Oubliez les mots techniques. Imaginez un salarié en charge de tout le numérique : le site, les demandes, les relances, les outils, la sécurité. Studio, c’est cette équipe, à prix fixe, sans recruter. Ensuite montrez un projet concret proche de leur activité — c’est toujours plus clair qu’une explication.","nextStep":"Envoyez un projet proche depuis le copilote, puis proposez 20 minutes.","proof":"Montrez le projet le plus proche trouvé dans le copilote."}'::jsonb, array['comprends pas', 'understand', 'c’est quoi', 'what is', 'flou', 'unclear']::text[], 82, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'maisonaurelia', 'en', 1, 'draft', p.id, 'hospitality', null, null, 'Maison Aurélia', 'A boutique-hotel site designed to turn a visit into a direct booking.', '{"type":"demo","name":"Maison Aurélia","offer":"premium","sector":"Hospitality","clientType":"Boutique hotel","description":"A boutique-hotel site designed to turn a visit into a direct booking.","problem":"Independent hotels depend on booking platforms; their own site must justify the rate and convert without detours.","solution":"Immersive photography, rooms and suites with rates, the experience (concierge, restaurant, wellness) and booking available at any time, in four languages.","features":["Rooms & rates","Online booking","4 languages","Premium art direction"],"argument":"Show it to any independent hotel or guest house: this is what “making people want to book direct” looks like.","url":"https://template-hotel-six.vercel.app/fr","image":"/portfolio/maisonaurelia.webp","imageMobile":"/portfolio/maisonaurelia-mobile.webp"}'::jsonb, array['hôtel', 'hotel', 'hôtellerie', 'chambre d’hôtes', 'réservation']::text[], 300, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'maisonaurelia', 'fr', 1, 'draft', p.id, 'hospitality', null, null, 'Maison Aurélia', 'Un site d’hôtel de charme pensé pour transformer une visite en réservation directe.', '{"type":"demo","name":"Maison Aurélia","offer":"premium","sector":"Hôtellerie","clientType":"Hôtel de charme","description":"Un site d’hôtel de charme pensé pour transformer une visite en réservation directe.","problem":"Les hôtels indépendants dépendent des plateformes ; leur propre site doit justifier le tarif et convertir sans détour.","solution":"Photographies immersives, chambres et suites avec tarifs, mise en avant de l’expérience (conciergerie, table, bien-être) et réservation accessible à tout moment, en quatre langues.","features":["Chambres & tarifs","Réservation en ligne","4 langues","Direction artistique premium"],"argument":"Montrez-le à tout hôtel indépendant ou chambre d’hôtes : voilà à quoi ressemble « donner envie de réserver en direct ».","url":"https://template-hotel-six.vercel.app/fr","image":"/portfolio/maisonaurelia.webp","imageMobile":"/portfolio/maisonaurelia-mobile.webp"}'::jsonb, array['hôtel', 'hotel', 'hôtellerie', 'chambre d’hôtes', 'réservation']::text[], 300, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'conciergerie', 'en', 1, 'draft', p.id, 'service-providers', null, null, 'Conciergerie St-Marie', 'A premium showcase for a concierge company addressing owners and travellers.', '{"type":"client","name":"Conciergerie St-Marie","offer":"pro","sector":"Concierge services","clientType":"Rental concierge","description":"A premium showcase for a concierge company addressing owners and travellers.","problem":"A concierge sells an invisible service — peace of mind — to two audiences at once: owners and guests.","solution":"A clean, high-end site: refined typography, clear services, trust signals and a path that always leads to contact (phone and form).","features":["Premium showcase","Two audiences, one path","Contact always visible","Local SEO"],"argument":"For service businesses that sell trust: the image must be as premium as the service.","url":"https://www.conciergeriestmarie.com","image":"/portfolio/conciergerie.webp","imageMobile":"/portfolio/conciergerie-mobile.webp"}'::jsonb, array['conciergerie', 'location saisonnière', 'hôtellerie', 'hospitality', 'premium']::text[], 301, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'conciergerie', 'fr', 1, 'draft', p.id, 'service-providers', null, null, 'Conciergerie St-Marie', 'Une vitrine premium pour une conciergerie qui s’adresse aux propriétaires et aux voyageurs.', '{"type":"client","name":"Conciergerie St-Marie","offer":"pro","sector":"Conciergerie","clientType":"Conciergerie de locations","description":"Une vitrine premium pour une conciergerie qui s’adresse aux propriétaires et aux voyageurs.","problem":"Une conciergerie vend un service invisible — la tranquillité — à deux publics à la fois : propriétaires et voyageurs.","solution":"Un site épuré et haut de gamme : typographies raffinées, services clairs, preuves de confiance et un parcours qui mène toujours au contact (téléphone et formulaire).","features":["Vitrine premium","Deux publics, un parcours","Contact toujours visible","SEO local"],"argument":"Pour les prestataires qui vendent de la confiance : l’image doit être aussi premium que le service.","url":"https://www.conciergeriestmarie.com","image":"/portfolio/conciergerie.webp","imageMobile":"/portfolio/conciergerie-mobile.webp"}'::jsonb, array['conciergerie', 'location saisonnière', 'hôtellerie', 'hospitality', 'premium']::text[], 301, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'mcrenov', 'en', 1, 'draft', p.id, 'renovation', null, null, 'MC Renov', 'A showcase built around finished projects, with a quote request on every page.', '{"type":"client","name":"MC Renov","offer":"pro","sector":"Renovation","clientType":"Renovation company","description":"A showcase built around finished projects, with a quote request on every page.","problem":"Excellent work, but a reputation limited to word of mouth and no credible presence to reassure private clients.","solution":"A sober site structured around project galleries, clear services and a quote form reachable from every page, with local SEO.","features":["Project galleries","Quote request form","Local SEO","Professional domain"],"argument":"For trades: their projects sell for them — as long as people can see them.","image":"/portfolio/mcrenov.webp","imageMobile":"/portfolio/mcrenov-mobile.webp"}'::jsonb, array['rénovation', 'artisan', 'btp', 'bâtiment', 'devis', 'chantier']::text[], 302, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'mcrenov', 'fr', 1, 'draft', p.id, 'renovation', null, null, 'MC Renov', 'Une vitrine construite autour des chantiers réalisés, avec une demande de devis sur chaque page.', '{"type":"client","name":"MC Renov","offer":"pro","sector":"Rénovation","clientType":"Entreprise de rénovation","description":"Une vitrine construite autour des chantiers réalisés, avec une demande de devis sur chaque page.","problem":"Un excellent travail, mais une réputation limitée au bouche-à-oreille et aucune présence crédible pour rassurer les particuliers.","solution":"Un site sobre structuré autour des galeries de chantiers, des prestations claires et d’un formulaire de devis accessible partout, avec SEO local.","features":["Galeries de chantiers","Formulaire de devis","SEO local","Nom de domaine professionnel"],"argument":"Pour les artisans : leurs chantiers vendent pour eux — à condition qu’on puisse les voir.","image":"/portfolio/mcrenov.webp","imageMobile":"/portfolio/mcrenov-mobile.webp"}'::jsonb, array['rénovation', 'artisan', 'btp', 'bâtiment', 'devis', 'chantier']::text[], 302, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'madauto', 'en', 1, 'draft', p.id, 'garages', null, null, 'Mada Auto', 'A platform that identifies the car from its plate and links compatible parts and services.', '{"type":"client","name":"Mada Auto","offer":"premium","sector":"Car repair","clientType":"All-make garage","description":"A platform that identifies the car from its plate and links compatible parts and services.","problem":"Every request cost the garage time: identify the vehicle, find compatible parts, quote, answer the phone.","solution":"Plate lookup on the home page, e-commerce APIs linking compatible parts and services, cart, free quote request, multilingual.","features":["Plate lookup API","Compatible parts & services","Cart & online quote","Multilingual"],"argument":"Proof that Studio goes beyond a site: the platform does part of the workshop’s admin.","url":"https://madauto-to.vercel.app","image":"/portfolio/madauto.webp","imageMobile":"/portfolio/madauto-mobile.webp"}'::jsonb, array['garage', 'automobile', 'auto', 'mécanique', 'pièces', 'devis']::text[], 303, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'madauto', 'fr', 1, 'draft', p.id, 'garages', null, null, 'Mada Auto', 'Une plateforme qui identifie le véhicule par sa plaque et relie pièces et prestations compatibles.', '{"type":"client","name":"Mada Auto","offer":"premium","sector":"Garage automobile","clientType":"Garage toutes marques","description":"Une plateforme qui identifie le véhicule par sa plaque et relie pièces et prestations compatibles.","problem":"Chaque demande coûtait du temps au garage : identifier le véhicule, trouver les pièces, faire le devis, répondre au téléphone.","solution":"Identification par plaque dès l’accueil, API e-commerce reliant pièces et prestations compatibles, panier, devis gratuit, multilingue.","features":["API plaque d’immatriculation","Pièces & prestations compatibles","Panier & devis en ligne","Multilingue"],"argument":"La preuve que Studio va au-delà du site : la plateforme fait une partie de l’administratif de l’atelier.","url":"https://madauto-to.vercel.app","image":"/portfolio/madauto.webp","imageMobile":"/portfolio/madauto-mobile.webp"}'::jsonb, array['garage', 'automobile', 'auto', 'mécanique', 'pièces', 'devis']::text[], 303, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'autosold', 'en', 1, 'draft', p.id, 'garages', null, null, 'AutoSold', 'A vehicle catalogue with full listings and direct contact at every step.', '{"type":"demo","name":"AutoSold","offer":"pro","sector":"Car sales","clientType":"Car dealer","description":"A vehicle catalogue with full listings and direct contact at every step.","problem":"Selling a car online means recreating the trust of a face-to-face visit, mostly on a phone.","solution":"Filterable catalogue, complete vehicle pages with large photos, highlights, and phone + WhatsApp buttons everywhere. Mobile-first.","features":["Filterable catalogue","Vehicle pages","WhatsApp contact","Mobile-first"],"argument":"Show it to dealers and used-car sellers: the stock is presented like a showroom, open 24/7.","url":"https://autosoldorigin.vercel.app","image":"/portfolio/autosold.webp","imageMobile":"/portfolio/autosold-mobile.webp"}'::jsonb, array['automobile', 'voiture', 'concession', 'occasion', 'véhicules']::text[], 304, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'autosold', 'fr', 1, 'draft', p.id, 'garages', null, null, 'AutoSold', 'Un catalogue de véhicules avec fiches complètes et contact direct à chaque étape.', '{"type":"demo","name":"AutoSold","offer":"pro","sector":"Vente automobile","clientType":"Concession / négociant","description":"Un catalogue de véhicules avec fiches complètes et contact direct à chaque étape.","problem":"Vendre une voiture en ligne, c’est recréer la confiance d’un face-à-face, surtout sur téléphone.","solution":"Catalogue filtrable, fiches véhicules complètes avec grandes photos, points forts et boutons téléphone + WhatsApp partout. Mobile-first.","features":["Catalogue filtrable","Fiches véhicules","Contact WhatsApp","Mobile-first"],"argument":"À montrer aux concessions et vendeurs d’occasion : le stock présenté comme un showroom, ouvert 24 h/24.","url":"https://autosoldorigin.vercel.app","image":"/portfolio/autosold.webp","imageMobile":"/portfolio/autosold-mobile.webp"}'::jsonb, array['automobile', 'voiture', 'concession', 'occasion', 'véhicules']::text[], 304, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'pizzaflash', 'en', 1, 'draft', p.id, 'restaurants', null, null, 'Pizza Flash', 'A pizzeria’s own ordering channel: menu, prices, hours and delivery area at a glance.', '{"type":"demo","name":"Pizza Flash","offer":"pro","sector":"Restaurant","clientType":"Pizzeria","description":"A pizzeria’s own ordering channel: menu, prices, hours and delivery area at a glance.","problem":"Every second of friction online sends the order to big platforms and their commissions.","solution":"Appetising visuals, a clear menu with prices, hours and delivery area visible immediately, and an ordering path with a minimum of clicks.","features":["Online menu","Fast ordering path","Delivery area & hours","Mobile-first"],"argument":"For restaurants: their own channel next to the apps — clear menu, simple order.","url":"https://pizzaflashorigin.vercel.app","image":"/portfolio/pizzaflash.webp","imageMobile":"/portfolio/pizzaflash-mobile.webp"}'::jsonb, array['pizzeria', 'restaurant', 'commande', 'livraison', 'menu']::text[], 305, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'pizzaflash', 'fr', 1, 'draft', p.id, 'restaurants', null, null, 'Pizza Flash', 'Le canal de commande d’une pizzeria : carte, prix, horaires et zone de livraison en un coup d’œil.', '{"type":"demo","name":"Pizza Flash","offer":"pro","sector":"Restauration","clientType":"Pizzeria","description":"Le canal de commande d’une pizzeria : carte, prix, horaires et zone de livraison en un coup d’œil.","problem":"Chaque seconde de friction en ligne envoie la commande vers les grandes plateformes et leurs commissions.","solution":"Visuels appétissants, carte claire avec prix, horaires et zone de livraison visibles tout de suite, et parcours de commande en un minimum de clics.","features":["Carte en ligne","Commande rapide","Zone & horaires de livraison","Mobile-first"],"argument":"Pour les restaurants : leur canal à eux à côté des applis — carte claire, commande simple.","url":"https://pizzaflashorigin.vercel.app","image":"/portfolio/pizzaflash.webp","imageMobile":"/portfolio/pizzaflash-mobile.webp"}'::jsonb, array['pizzeria', 'restaurant', 'commande', 'livraison', 'menu']::text[], 305, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'manight', 'en', 1, 'draft', p.id, 'restaurants', null, null, 'Ma''Night', 'A strong identity, a menu in one tap, a cart and direct phone access for evening orders.', '{"type":"client","name":"Ma''Night","offer":"pro","sector":"Restaurant","clientType":"Evening street-food restaurant","description":"A strong identity, a menu in one tap, a cart and direct phone access for evening orders.","problem":"Late at night, platforms dominate “food tonight” searches; the restaurant needed a direct, memorable channel.","solution":"A warm night-time identity, clear online menu, cart and ordering, delivery page and phone at every step, multilingual and mobile-first.","features":["Online menu & cart","Delivery page","Phone at every step","Multilingual"],"argument":"Show it to restaurants that live on evening orders: identity + direct ordering.","url":"https://madanight.vercel.app","image":"/portfolio/manight.webp","imageMobile":"/portfolio/manight-mobile.webp"}'::jsonb, array['restaurant', 'street food', 'livraison', 'commande', 'soir']::text[], 306, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'manight', 'fr', 1, 'draft', p.id, 'restaurants', null, null, 'Ma''Night', 'Une identité forte, une carte en un geste, un panier et le téléphone direct pour les commandes du soir.', '{"type":"client","name":"Ma''Night","offer":"pro","sector":"Restauration","clientType":"Restaurant street-food du soir","description":"Une identité forte, une carte en un geste, un panier et le téléphone direct pour les commandes du soir.","problem":"Le soir, les plateformes dominent les recherches « manger ce soir » ; le restaurant avait besoin d’un canal direct et mémorable.","solution":"Une identité nocturne chaleureuse, carte en ligne claire, panier et commande, page livraison et téléphone à chaque étape, multilingue et mobile-first.","features":["Carte & panier en ligne","Page livraison","Téléphone à chaque étape","Multilingue"],"argument":"À montrer aux restaurants qui vivent des commandes du soir : identité + commande directe.","url":"https://madanight.vercel.app","image":"/portfolio/manight.webp","imageMobile":"/portfolio/manight-mobile.webp"}'::jsonb, array['restaurant', 'street food', 'livraison', 'commande', 'soir']::text[], 306, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'case_study', 'balanta', 'en', 1, 'draft', p.id, 'restaurants', null, null, 'Balanta', 'A warm showcase that makes people hungry, tells the product’s story and simplifies ordering.', '{"type":"client","name":"Balanta","offer":"pro","sector":"Artisan food","clientType":"Home-made food maker","description":"A warm showcase that makes people hungry, tells the product’s story and simplifies ordering.","problem":"An authentic product sold only through word of mouth and social media.","solution":"Large appetising photos, recipes and home-made story, and a direct ordering path — simple and authentic tone.","features":["Photo gallery","Product story","Simple ordering","Warm custom design"],"argument":"For food makers and caterers who sell through DMs today.","url":"https://balanta-croc-pastel.vercel.app","image":"/portfolio/balanta.webp","imageMobile":"/portfolio/balanta-mobile.webp"}'::jsonb, array['traiteur', 'artisan', 'fait-maison', 'commande', 'food']::text[], 307, null from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
