insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'stage_guide', 'stage.new', 'fr', 1, 'active', p.id, null, null, null, 'Obtenir une réponse.', null, '{"goal":"Obtenir une réponse.","why":"Vous n’avez encore eu aucun échange avec cette personne.","action":"Envoyez le premier message.","say":"first_contact","show":"none","dont":"Ne cherchez pas encore à vendre toute l’offre Studio. Un message court, une question.","outcomes":[{"label":"J’ai envoyé le message","to":"contacted","event":"message_sent"}],"escalate":"Pas sûr de la bonne approche ? Demandez à Studio dans votre fil Support — vous ne paraîtrez pas amateur.","stage":"new"}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
