insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'stage_guide', 'stage.qualified', 'en', 1, 'active', p.id, null, null, null, 'Spark interest with their own problem.', null, '{"goal":"Spark interest with their own problem.","why":"You know what bothers them: connect it to what Studio does.","action":"Repeat their problem in one sentence, then say how Studio takes it off their hands.","show":"none","dont":"Talk about their problem, not about technology.","outcomes":[{"label":"They’re interested","to":"interested","event":"interest"},{"label":"Not now","to":"lost","event":"lost"}],"stage":"qualified"}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'stage_guide', 'stage.qualified', 'fr', 1, 'active', p.id, null, null, null, 'Susciter l’intérêt avec son propre problème.', null, '{"goal":"Susciter l’intérêt avec son propre problème.","why":"Vous savez ce qui le/la gêne : reliez-le à ce que fait Studio.","action":"Reformulez son problème en une phrase, puis dites comment Studio l’en débarrasse.","show":"none","dont":"Parlez de son problème, pas de technologie.","outcomes":[{"label":"Il/elle est intéressé(e)","to":"interested","event":"interest"},{"label":"Pas maintenant","to":"lost","event":"lost"}],"stage":"qualified"}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
