insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'stage_guide', 'stage.proposal', 'en', 1, 'active', p.id, null, null, null, 'Help them decide.', null, '{"goal":"Help them decide.","why":"They have the offer. Answer questions; don’t push.","action":"Ask if anything is unclear, then follow up at the planned dates.","show":"offer","outcomes":[{"label":"They want a meeting","to":"appointment","event":"meeting"},{"label":"They want a quote","to":"checkout","event":"quote"},{"label":"They bought","to":"won","event":"won"},{"label":"Not now","to":"lost","event":"lost"}],"escalate":"Contract, invoice, technical scope or custom need: hand over to Studio.","stage":"proposal"}'::jsonb, array[]::text[], 6, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
