insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'reply', 'send-info', 'en', 1, 'active', p.id, null, null, null, '“Send me some information.”', null, '{"said":"“Send me some information.”","meaning":"Often a polite way to end the call — make the information personal.","answer":"With pleasure. So I don’t send you a generic brochure: what matters most to you — getting more requests, saving time, or not dealing with the technical side?","question":"When can I call you back to see if it fits?","to":"interested","next":"Send ONE project close to them + your page, and agree on a date to talk again.","level":2,"show":"case_study"}'::jsonb, array[]::text[], 2, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'reply', 'send-info', 'fr', 1, 'active', p.id, null, null, null, '« Envoyez-moi des informations. »', null, '{"said":"« Envoyez-moi des informations. »","meaning":"Souvent une façon polie de conclure — rendez l’information personnelle.","answer":"Avec plaisir. Pour ne pas vous envoyer une brochure générique : qu’est-ce qui compte le plus pour vous — plus de demandes, gagner du temps, ou ne plus gérer la technique ?","question":"Quand puis-je vous rappeler pour voir si ça vous correspond ?","to":"interested","next":"Envoyez UN projet proche + votre page, et convenez d’une date pour en reparler.","level":2,"show":"case_study"}'::jsonb, array[]::text[], 2, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'reply', 'already-website', 'en', 1, 'active', p.id, null, null, null, '“I already have a website.”', null, '{"said":"“I already have a website.”","meaning":"Not a no: they think Studio is “a website”.","answer":"Perfect, keep it if it works. Studio is not just a site: it’s the team that runs your whole digital side — requests, follow-ups, tools.","question":"What happens today after someone fills in your form?","objection":"already-website","to":"qualified","next":"Listen to the answer, then show a project where requests are centralised.","level":2,"show":"case_study"}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'reply', 'already-website', 'fr', 1, 'active', p.id, null, null, null, '« J’ai déjà un site. »', null, '{"said":"« J’ai déjà un site. »","meaning":"Pas un refus : il/elle pense que Studio est « un site ».","answer":"Parfait, gardez-le s’il fonctionne. Studio n’est pas juste un site : c’est l’équipe qui fait tourner tout votre numérique — demandes, relances, outils.","question":"Que se passe-t-il aujourd’hui après qu’on a rempli votre formulaire ?","objection":"already-website","to":"qualified","next":"Écoutez la réponse, puis montrez un projet où les demandes sont centralisées.","level":2,"show":"case_study"}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'reply', 'someone-handles-it', 'en', 1, 'active', p.id, null, null, null, '“I already have someone who handles that.”', null, '{"said":"“I already have someone who handles that.”","meaning":"A relationship to respect — and maybe a gap to find.","answer":"That’s great. Studio often works alongside: is that person available all year for hosting, security, changes and follow-ups?","question":"What would you like them to do that they don’t have time for?","to":"qualified","next":"If there’s a gap, note it. If not, leave a good impression and come back later.","level":2,"show":"none"}'::jsonb, array[]::text[], 4, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
