insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'reply', 'no-time', 'en', 1, 'active', p.id, null, null, null, '“I don’t have time.”', null, '{"said":"“I don’t have time.”","meaning":"Not the right moment — or they fear more work.","answer":"Precisely: Studio is for people who don’t have time. We build and run it; you answer the requests.","question":"When would be a calmer moment to look at it for 10 minutes?","objection":"no-time","next":"Agree on a date and note it — never insist.","level":2,"show":"none"}'::jsonb, array[]::text[], 5, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
