insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'fact', 'fact.promises', 'en', 1, 'active', p.id, null, null, null, 'What can I promise — and what not?', null, '{"category":"promises","level":1,"question":"What can I promise — and what not?","answer":"Promise only what is written here and on the official offer pages. When in doubt, ask Studio.","can":["The official offers and their published prices","That Studio designs, builds and runs what the chosen offer includes","That the client owns their code and data (Pro and Premium)","That Studio answers technical and contract questions"],"cannot":["A discount (other than your own promo code)","A delivery date other than the one announced on the offer","A feature not listed in the offer","Results: revenue, number of clients, bookings, rankings","A guarantee or a commitment not written in the contract"]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'fact', 'fact.promises', 'fr', 1, 'active', p.id, null, null, null, 'Que puis-je promettre — et que ne dois-je pas promettre ?', null, '{"category":"promises","level":1,"question":"Que puis-je promettre — et que ne dois-je pas promettre ?","answer":"Ne promettez que ce qui est écrit ici et sur les pages officielles des offres. En cas de doute, demandez à Studio.","can":["Les offres officielles et leurs prix publiés","Que Studio conçoit, construit et fait fonctionner ce que l’offre choisie inclut","Que le client reste propriétaire de son code et de ses données (Pro et Premium)","Que Studio répond aux questions techniques et contractuelles"],"cannot":["Une remise (autre que votre propre code promo)","Un délai autre que celui annoncé sur l’offre","Une fonctionnalité qui n’est pas listée dans l’offre","Des résultats : chiffre d’affaires, nombre de clients, réservations, classement","Une garantie ou un engagement non écrit au contrat"]}'::jsonb, array[]::text[], 0, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'fact', 'fact.company', 'en', 1, 'active', p.id, null, null, null, 'Who is Studio?', null, '{"category":"company","level":1,"question":"Who is Studio?","answer":"Studio ATS (“à ton service”) is the team that builds and runs the digital infrastructure of independents and small businesses: presence, tools, requests, follow-ups, hosting, security."}'::jsonb, array[]::text[], 1, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
