insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'fact', 'fact.offers', 'en', 1, 'active', p.id, null, null, null, 'What are the offers?', null, '{"category":"offers","level":1,"question":"What are the offers?","answer":"Three offers of the same product: Studio One (a ready-to-use presence, bought once, delivered as is), Studio Pro (a complete, customisable site maintained all year), Studio Premium (the whole commercial ecosystem — CRM, payments, automations — operated by Studio). Details on the official pricing page."}'::jsonb, array[]::text[], 3, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
