insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'fact', 'fact.pricing', 'en', 1, 'active', p.id, null, null, null, 'What are the prices? Can I negotiate?', null, '{"category":"pricing","level":1,"question":"What are the prices? Can I negotiate?","answer":"The official prices are shown at the top of this page, read live from the catalogue. They are the same for everyone. You never negotiate: the only reduction you may offer is your own promo code, which is deducted from your commission."}'::jsonb, array[]::text[], 4, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'fact', 'fact.pricing', 'fr', 1, 'active', p.id, null, null, null, 'Quels sont les prix ? Puis-je négocier ?', null, '{"category":"pricing","level":1,"question":"Quels sont les prix ? Puis-je négocier ?","answer":"Les prix officiels sont affichés en haut de cette page, lus en direct dans le catalogue. Ils sont identiques pour tous. Vous ne négociez jamais : la seule réduction possible est votre propre code promo, déduit de votre commission."}'::jsonb, array[]::text[], 4, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'fact', 'fact.process', 'en', 1, 'active', p.id, null, null, null, 'How does it work for the client?', null, '{"category":"process","level":1,"question":"How does it work for the client?","answer":"1. The client chooses an offer (online, or through a client dossier prepared with Studio). 2. Studio gathers the needs. 3. Studio builds and configures. 4. Launch, then Studio runs it according to the offer."}'::jsonb, array[]::text[], 5, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
