insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'fact', 'fact.commissions', 'en', 1, 'active', p.id, null, null, null, 'How am I paid?', null, '{"category":"commissions","level":1,"question":"How am I paid?","answer":"Your rate and your sponsor rate are shown at the top of this page. A commission is created when Studio receives the payment, stays “pending” during the validation period (refunds, disputes), becomes “available”, then is paid out. Annual renewals pay again."}'::jsonb, array[]::text[], 10, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
