insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'signal', 'marketplace-dependence', 'fr', 1, 'active', p.id, null, null, null, '« L’essentiel de mon activité passe par une plateforme. »', null, '{"signal":"« L’essentiel de mon activité passe par une plateforme. »","problem":"L’entreprise ne maîtrise pas toute la relation client.","question":"Quelles informations et quel suivi gardez-vous après la transaction ?","studio":"Construire un canal propre à côté de la plateforme.","proof":"Montrez une page commerce ou hôtellerie pertinente sans promettre d’économie de commission.","next":"Identifiez la relation que l’entreprise peut légalement et concrètement conserver."}'::jsonb, array['plateforme', 'marketplace', 'dépendance']::text[], 17, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'signal', 'team-cannot-see', 'en', 1, 'active', p.id, null, null, null, '“My team can’t see where a request stands.”', null, '{"signal":"“My team can’t see where a request stands.”","problem":"Ownership and status are unclear.","question":"How does someone know what the next action is without asking you?","studio":"Give each opportunity a stage, owner and next action.","proof":"Show the CRM board and next-best-action card.","next":"Take one open opportunity and assign its exact next action."}'::jsonb, array['équipe', 'visibilité', 'status']::text[], 18, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'signal', 'team-cannot-see', 'fr', 1, 'active', p.id, null, null, null, '« Mon équipe ne sait pas où en est une demande. »', null, '{"signal":"« Mon équipe ne sait pas où en est une demande. »","problem":"Le responsable et le statut ne sont pas clairs.","question":"Comment quelqu’un connaît-il la prochaine action sans vous demander ?","studio":"Donner à chaque opportunité une étape, un responsable et une prochaine action.","proof":"Montrez le CRM et la carte de prochaine action.","next":"Prenez une opportunité ouverte et attribuez-lui une prochaine action exacte."}'::jsonb, array['équipe', 'visibilité', 'status']::text[], 18, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'signal', 'ready-to-change', 'en', 1, 'active', p.id, null, null, null, '“We know the current setup has to change.”', null, '{"signal":"“We know the current setup has to change.”","problem":"There is intent, but the scope and risk are still unclear.","question":"What must keep working during the change?","studio":"Plan the infrastructure around the real process and migrate with Studio oversight.","proof":"Show the official process and a comparable verified project.","next":"Capture goals, constraints and existing tools, then hand over to Studio."}'::jsonb, array['refonte', 'changer', 'migration']::text[], 19, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'signal', 'ready-to-change', 'fr', 1, 'active', p.id, null, null, null, '« Nous savons que le système actuel doit changer. »', null, '{"signal":"« Nous savons que le système actuel doit changer. »","problem":"L’intention existe, mais le périmètre et les risques restent flous.","question":"Qu’est-ce qui doit absolument continuer à fonctionner pendant le changement ?","studio":"Concevoir l’infrastructure autour du processus réel et migrer avec l’équipe Studio.","proof":"Montrez le processus officiel et un projet vérifié comparable.","next":"Notez objectifs, contraintes et outils existants, puis passez à Studio."}'::jsonb, array['refonte', 'changer', 'migration']::text[], 19, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'referral', 'en', 1, 'active', p.id, null, 'phone', 'first_contact', 'Call after a referral', 'Use the trust of the introduction without assuming a need.', '{"steps":[{"type":"opening","text":"Hello {{firstName}}, {{advisorName}} here. [Referrer] suggested I call because you might be reviewing how {{company}} handles its digital tools. Is now a bad time?"},{"type":"question","text":"What made the topic worth discussing now?"},{"type":"listen","text":"Timing, operational friction, ownership, or a concrete project. Use their words."},{"type":"question","text":"What happens today from a new enquiry to the next follow-up?"},{"type":"response","text":"Studio builds and runs the digital infrastructure around that process. I can show you one relevant example."},{"type":"cta","text":"Would a 20-minute diagnostic with Studio be useful?"}]}'::jsonb, array[]::text[], 90, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'referral', 'fr', 1, 'active', p.id, null, 'phone', 'first_contact', 'Appel après recommandation', 'Utiliser la confiance de l’introduction sans supposer un besoin.', '{"steps":[{"type":"opening","text":"Bonjour {{firstName}}, {{advisorName}} à l’appareil. [Personne] m’a conseillé de vous appeler car vous réfléchissez peut-être à la façon dont {{company}} gère son numérique. Je vous prends au mauvais moment ?"},{"type":"question","text":"Qu’est-ce qui rend le sujet pertinent maintenant ?"},{"type":"listen","text":"Calendrier, friction opérationnelle, responsabilité ou projet concret. Reprenez leurs mots."},{"type":"question","text":"Que se passe-t-il aujourd’hui entre une nouvelle demande et la relance suivante ?"},{"type":"response","text":"Studio construit et fait fonctionner l’infrastructure numérique autour de ce parcours. Je peux vous montrer un exemple pertinent."},{"type":"cta","text":"Un diagnostic de 20 minutes avec Studio vous serait-il utile ?"}]}'::jsonb, array[]::text[], 90, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'inbound', 'en', 1, 'active', p.id, null, 'phone', 'interested', 'Inbound call', 'Turn an incoming question into a short diagnosis.', '{"steps":[{"type":"opening","text":"Thank you for calling. Before I answer, what prompted you to contact Studio today?"},{"type":"question","text":"What is not working well enough in the current setup?"},{"type":"listen","text":"Problem, consequence, people affected, urgency."},{"type":"question","text":"What have you already tried?"},{"type":"response","text":"I’ll summarise what I heard, then I’ll tell you whether Studio looks relevant."},{"type":"cta","text":"The next useful step is a Studio diagnostic. Shall we book it?"}]}'::jsonb, array[]::text[], 91, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'inbound', 'fr', 1, 'active', p.id, null, 'phone', 'interested', 'Appel entrant', 'Transformer une demande entrante en diagnostic court.', '{"steps":[{"type":"opening","text":"Merci de nous appeler. Avant de répondre, qu’est-ce qui vous amène vers Studio aujourd’hui ?"},{"type":"question","text":"Qu’est-ce qui ne fonctionne pas assez bien dans votre organisation actuelle ?"},{"type":"listen","text":"Problème, conséquence, personnes concernées, urgence."},{"type":"question","text":"Qu’avez-vous déjà essayé ?"},{"type":"response","text":"Je résume ce que j’ai compris, puis je vous dis si Studio semble pertinent."},{"type":"cta","text":"La prochaine étape utile est un diagnostic Studio. On le planifie ?"}]}'::jsonb, array[]::text[], 91, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'studio-handoff', 'en', 1, 'active', p.id, null, 'phone', 'closing', 'Hand over to Studio', 'Introduce the team without losing context or attribution.', '{"steps":[{"type":"opening","text":"I’d like to bring the Studio team in so you get precise answers."},{"type":"response","text":"I’ll send them: your current situation, the problem you want to solve, your timing and the tools already in place."},{"type":"question","text":"What is the one question you absolutely want answered on that call?"},{"type":"listen","text":"Repeat the exact question; do not reinterpret technical or legal details."},{"type":"cta","text":"What time and contact details should I pass to Studio? I remain attached to the opportunity."}]}'::jsonb, array[]::text[], 92, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'call_script', 'studio-handoff', 'fr', 1, 'active', p.id, null, 'phone', 'closing', 'Passage de relais à Studio', 'Présenter l’équipe sans perdre le contexte ni l’attribution.', '{"steps":[{"type":"opening","text":"Je préfère faire intervenir l’équipe Studio pour que vous ayez des réponses précises."},{"type":"response","text":"Je leur transmets : votre situation actuelle, le problème à résoudre, votre calendrier et les outils déjà en place."},{"type":"question","text":"Quelle est la question à laquelle vous voulez absolument une réponse pendant cet échange ?"},{"type":"listen","text":"Reprenez la question exacte ; ne réinterprétez pas les détails techniques ou juridiques."},{"type":"cta","text":"Quel créneau et quelles coordonnées dois-je transmettre à Studio ? Je reste rattaché à l’opportunité."}]}'::jsonb, array[]::text[], 92, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-after-referral', 'en', 1, 'active', p.id, null, 'email', 'first_contact', 'After a referral', null, '{"subject":"[Referrer] suggested we speak about {{company}}","preview":"One question before I send anything.","body":"Hello {{firstName}},\n\n[Referrer] suggested I contact you. I work with Studio ATS, the team that builds, connects and runs the digital infrastructure around a business.\n\nRather than send a generic presentation: what part of your current process takes the most time or loses the most information?\n\nI’ll reply with one relevant example — or tell you honestly if Studio is not the right fit.","cta":"Reply with the main friction"}'::jsonb, array['referral', 'introduction']::text[], 90, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-after-referral', 'fr', 1, 'active', p.id, null, 'email', 'first_contact', 'Après une recommandation', null, '{"subject":"[Personne] m’a conseillé de vous parler de {{company}}","preview":"Une question avant de vous envoyer quoi que ce soit.","body":"Bonjour {{firstName}},\n\n[Personne] m’a conseillé de vous contacter. Je travaille avec Studio ATS, l’équipe qui construit, connecte et fait fonctionner l’infrastructure numérique autour d’une entreprise.\n\nPlutôt que vous envoyer une présentation générique : quelle partie de votre fonctionnement actuel vous prend le plus de temps ou fait perdre le plus d’informations ?\n\nJe vous répondrai avec un seul exemple pertinent — ou je vous dirai franchement si Studio n’est pas adapté.","cta":"Répondre avec la friction principale"}'::jsonb, array['recommandation', 'introduction']::text[], 90, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-after-diagnostic', 'en', 1, 'active', p.id, null, 'email', 'after_call', 'After the diagnostic', null, '{"subject":"{{company}} — the problem, impact and next step","preview":"A factual recap before involving Studio.","body":"Hello {{firstName}},\n\nHere is what I understood:\n• Current situation: [one sentence]\n• Friction: [one sentence]\n• Consequence: [time, missed opportunity or lack of clarity — no invented figure]\n• Desired outcome: [one sentence]\n\nStudio could be relevant because it can build and run the infrastructure around this process. The next step is a call with the team to confirm scope, feasibility and the right offer.\n\nPlease correct anything I misunderstood.","cta":"Confirm the recap"}'::jsonb, array['diagnostic', 'recap']::text[], 91, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'email_template', 'email-after-diagnostic', 'fr', 1, 'active', p.id, null, 'email', 'after_call', 'Après le diagnostic', null, '{"subject":"{{company}} — le problème, l’impact et la prochaine étape","preview":"Un récapitulatif factuel avant de faire intervenir Studio.","body":"Bonjour {{firstName}},\n\nVoici ce que j’ai compris :\n• Situation actuelle : [une phrase]\n• Friction : [une phrase]\n• Conséquence : [temps, opportunité perdue ou manque de clarté — sans chiffre inventé]\n• Résultat souhaité : [une phrase]\n\nStudio pourrait être pertinent car l’équipe peut construire et faire fonctionner l’infrastructure autour de ce parcours. La prochaine étape est un échange avec Studio pour confirmer le périmètre, la faisabilité et la bonne offre.\n\nCorrigez-moi si j’ai mal compris un point.","cta":"Confirmer le récapitulatif"}'::jsonb, array['diagnostic', 'récapitulatif']::text[], 91, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'send-information', 'en', 1, 'active', p.id, null, null, 'objection', '“Just send me the information.”', null, '{"objection":"“Just send me the information.”","meaning":"They may be genuinely interested, or politely ending the conversation.","questions":["What would be most useful to see: a similar project, the offers, or how Studio works?","When should I call back for your reaction?"],"short":"With pleasure. I’ll send one relevant item, not a pile of documents. What question should it answer?","long":"Turn a vague request into a specific resource and an agreed follow-up. Do not send every brochure: choose the closest verified project or official page, state why it is relevant and ask for a date to speak again.","nextStep":"Send one resource and log the agreed follow-up date.","proof":"Use the closest verified project or the official offer page."}'::jsonb, array['informations', 'brochure', 'send info']::text[], 100, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'send-information', 'fr', 1, 'active', p.id, null, null, 'objection', '« Envoyez-moi juste les informations. »', null, '{"objection":"« Envoyez-moi juste les informations. »","meaning":"La personne peut être sincèrement intéressée, ou conclure poliment la conversation.","questions":["Qu’est-ce qui vous serait le plus utile : un projet proche, les offres, ou le fonctionnement de Studio ?","Quand puis-je vous rappeler pour avoir votre retour ?"],"short":"Avec plaisir. Je vous envoie un seul élément pertinent, pas une pile de documents. À quelle question doit-il répondre ?","long":"Transformez une demande vague en ressource précise et en relance convenue. N’envoyez pas toutes les brochures : choisissez le projet vérifié ou la page officielle la plus proche, expliquez pourquoi, puis fixez une date pour en reparler.","nextStep":"Envoyez une ressource et notez la date de relance convenue.","proof":"Utilisez le projet vérifié le plus proche ou la page officielle des offres."}'::jsonb, array['informations', 'brochure', 'send info']::text[], 100, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'prefer-phone', 'en', 1, 'active', p.id, null, null, 'objection', '“My customers prefer to call.”', null, '{"objection":"“My customers prefer to call.”","meaning":"They fear losing the human relationship.","questions":["Which calls are genuinely useful conversations?","Which calls repeat practical questions?"],"short":"Keep the call. Studio can prepare it so you start with the right information instead of repeating the basics.","long":"Studio is not meant to remove human contact. It can answer practical questions, collect context and offer a time, so the call is more useful for both sides. The customer can still call when that is the best next step.","nextStep":"Choose what should happen before the call and what must stay human.","proof":"Show a guided request or booking flow."}'::jsonb, array['appel', 'téléphone', 'phone']::text[], 101, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'prefer-phone', 'fr', 1, 'active', p.id, null, null, 'objection', '« Mes clients préfèrent appeler. »', null, '{"objection":"« Mes clients préfèrent appeler. »","meaning":"Ils craignent de perdre la relation humaine.","questions":["Quels appels sont de vraies conversations utiles ?","Quels appels répètent des questions pratiques ?"],"short":"Gardez l’appel. Studio peut le préparer pour que vous commenciez avec les bonnes informations au lieu de répéter les bases.","long":"Studio n’a pas vocation à supprimer le contact humain. L’infrastructure peut répondre aux questions pratiques, recueillir le contexte et proposer un créneau, afin que l’appel soit plus utile des deux côtés. Le client peut toujours appeler quand c’est la bonne étape.","nextStep":"Choisissez ce qui doit se passer avant l’appel et ce qui doit rester humain.","proof":"Montrez un parcours de demande guidée ou de réservation."}'::jsonb, array['appel', 'téléphone', 'phone']::text[], 101, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'partner-approval', 'en', 1, 'active', p.id, null, null, 'objection', '“I need to discuss it with my partner.”', null, '{"objection":"“I need to discuss it with my partner.”","meaning":"Another decision-maker needs context; this is not a request for pressure.","questions":["What will matter most to them?","Would it help if Studio joined the conversation?"],"short":"Of course. Let’s make sure they receive the problem, the proposed scope and the official information — not a sales summary second-hand.","long":"Ask how the partner decides, what question they will raise and who owns the budget. Offer a joint Studio call if useful. Never ask the first contact to sell internally for you.","nextStep":"Send a concise recap and agree on a date for the joint conversation.","proof":"Use the official page and hand over if scope or contract is discussed."}'::jsonb, array['associé', 'partner', 'décideur']::text[], 102, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'partner-approval', 'fr', 1, 'active', p.id, null, null, 'objection', '« Je dois en parler à mon associé. »', null, '{"objection":"« Je dois en parler à mon associé. »","meaning":"Un autre décideur a besoin de contexte ; ce n’est pas une invitation à mettre la pression.","questions":["Qu’est-ce qui comptera le plus pour lui ou elle ?","Est-ce utile que Studio participe à l’échange ?"],"short":"Bien sûr. Assurons-nous qu’il ou elle reçoive le problème, le périmètre proposé et les informations officielles — pas un résumé commercial de seconde main.","long":"Demandez comment l’associé décide, quelle question il posera et qui porte le budget. Proposez un échange commun avec Studio si utile. Ne demandez jamais au premier contact de vendre à votre place en interne.","nextStep":"Envoyez un récapitulatif court et convenez d’une date pour l’échange commun.","proof":"Utilisez la page officielle et passez à Studio dès que le périmètre ou le contrat est discuté."}'::jsonb, array['associé', 'partner', 'décideur']::text[], 102, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-need', 'en', 1, 'active', p.id, null, null, 'objection', '“I don’t need it.”', null, '{"objection":"“I don’t need it.”","meaning":"There may be no current problem — or the value has not been connected to their reality.","questions":["What already works well enough today?","Is there anything you would still like to simplify?"],"short":"That may be true. If the current setup saves time, keeps information clear and has an owner, I won’t try to replace it.","long":"Do not manufacture pain. Ask what works and what does not. If no meaningful friction appears, leave the door open and stop. A bad-fit prospect is not an opportunity.","nextStep":"Mark the reason in the CRM and only schedule a later check-in if they ask.","proof":"No proof is needed unless they name a concrete friction."}'::jsonb, array['pas besoin', 'no need', 'inutile']::text[], 103, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
insert into public.sales_content (kind, key, locale, version, status, product_id, target_key, channel, stage, title, summary, body, tags, sort, published_at) select 'objection', 'no-need', 'fr', 1, 'active', p.id, null, null, 'objection', '« Je n’en ai pas besoin. »', null, '{"objection":"« Je n’en ai pas besoin. »","meaning":"Il n’y a peut-être aucun problème actuel — ou la valeur n’a pas été reliée à leur réalité.","questions":["Qu’est-ce qui fonctionne déjà suffisamment bien aujourd’hui ?","Y a-t-il malgré tout quelque chose que vous aimeriez simplifier ?"],"short":"C’est possible. Si le système actuel vous fait gagner du temps, garde l’information claire et a un responsable, je ne vais pas chercher à le remplacer.","long":"N’inventez pas de douleur. Demandez ce qui fonctionne et ce qui ne fonctionne pas. Si aucune friction significative n’apparaît, laissez la porte ouverte et arrêtez. Un prospect mal adapté n’est pas une opportunité.","nextStep":"Notez la raison dans le CRM et ne programmez un retour que s’il le demande.","proof":"Aucune preuve n’est nécessaire tant qu’aucune friction concrète n’est exprimée."}'::jsonb, array['pas besoin', 'no need', 'inutile']::text[], 103, now() from public.products p where p.slug = 'studio' on conflict (kind, key, locale, version) do nothing;
